fn cancel_run(sim : Simulator, id : String) : Result(Simulator, String) =
  match find(\(run) -> run.id == id, sim.runs) of
    None => Err("UNKNOWN_RUN")
    Some(run) =>
      if run.status == Completed || run.status == RunFailed || run.status == RunCancelled then Ok(sim)
      else
        let steps = map(\(step) -> if step.status == Pending then StepState { ..step, status = Cancelled } else step, run.steps)
        let status = if any(\(step) -> step.status == Running, steps) then Cancelling else RunCancelled
        Ok(replace_run(sim, RunState { ..run, steps = steps, status = status, cancel_requested = true }))

fn call_service(service : MockService, key : ActionKey, amount : Int, attempt : Int, failures : Int, lookup_only : Bool) : (MockService, String) =
  let found = has_effect(service, key)
  let failed_calls = length(filter(\(call) -> same_key(call.key, key) && call.outcome == "transient", service.calls))
  let outcome =
    if lookup_only then (if found then "found" else "missing")
    elif found then "replayed"
    elif failed_calls < failures then "transient"
    else "applied"
  let updated = MockService {
    calls = append(service.calls, [ServiceCall { key = key, attempt = attempt,
      kind = if lookup_only then "lookup" else "execute", outcome = outcome }]),
    effects = if outcome == "applied" then append(service.effects, [Effect { key = key, amount = amount }]) else service.effects
  }
  (updated, outcome)

