fn tick(sim : Simulator, workflow : Workflow, checkpoint : Option(Checkpoint)) : Result(Simulator, String) =
  match select_action(sim, workflow) of
    None => Ok(sim)
    Some(action) =>
      let running =
        if action.step.status == Pending then
          StepState { ..action.step, status = Running, attempts = action.step.attempts + 1 }
        else action.step
      let begun_run = replace_step(action.run, running)
      let begun = replace_run(sim, begun_run)
      if checkpoint == Some(AfterBegin) then Ok(Simulator { ..begun, up = false })
      else
        let key = ActionKey { run_id = action.run.id, step_id = running.id }
        let cancelling = begun_run.status == Cancelling
        let response = call_service(begun.service, key, action.definition.amount, running.attempts, action.definition.failures, cancelling)
        let called = Simulator { ..begun, service = fst(response) }
        let outcome = snd(response)
        if checkpoint == Some(AfterCall) then Ok(Simulator { ..called, up = false })
        elif cancelling then
          let reconciled = replace_step(begun_run, StepState { ..running,
            status = if outcome == "found" then Succeeded else Cancelled })
          Ok(replace_run(called, RunState { ..reconciled, status = RunCancelled }))
        elif outcome == "transient" then
          if running.attempts < workflow.max_attempts then
            if sim.now + workflow.retry_delay > time_limit() then Err("TIME_OVERFLOW")
            else
              let retry = StepState { ..running, status = Pending, ready_at = sim.now + workflow.retry_delay }
              Ok(replace_run(called, replace_step(begun_run, retry)))
          else
            let failed = replace_step(begun_run, StepState { ..running, status = Failed })
            let blocked = map(\(step) -> if step.status == Pending then StepState { ..step, status = Blocked } else step, failed.steps)
            Ok(replace_run(called, RunState { ..failed, status = RunFailed, steps = blocked }))
        else
          let completed = replace_step(begun_run, StepState { ..running, status = Succeeded })
          let finished =
            if all(\(step) -> step.status == Succeeded, completed.steps) then
              RunState { ..completed, status = Completed }
            else completed
          Ok(replace_run(called, finished))

